arguments.cmd:
cat > /app/chart.mmd <<'EOF'
%%{init: {
  "theme": "base",
  "themeVariables": {
    "fontFamily": "Inter, Arial, sans-serif",
    "xyChart": {
      "plotColorPalette": "#1f77b4,#d62728,#2ca02c,#ff7f0e"
    }
  }
}}%%
xychart-beta
    title "Global Fintech Disruption Crossover (2015–2024): Digital Adoption & Licensing Rise vs Branch Decline"
    x-axis "Year" [2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024]
    y-axis "Index / Count (Payment Penetration: %, Branches: thousands, Licenses: cumulative count)" 0 --> 900
    line "Digital Payment Penetration (Global avg, %)" [26.175, 29.9, 35.5, 41.975, 48.675, 57.85, 64.45, 70.2, 75.125, 79.55]
    line "Traditional Bank Branches (Global total, k)" [870.3, 857.3, 841.5, 822.2, 798.4, 761.2, 730.7, 700.3, 670.8, 643.2]
    line "Digital Bank Licenses (Global cumulative)" [4, 9, 17, 28, 43, 60, 76, 93, 109, 122]
    bar "Annual Branch Closures (Global, k)" [0, 13.0, 15.8, 19.3, 23.8, 37.2, 30.5, 30.4, 29.5, 27.6]
EOF

npx -y @mermaid-js/mermaid-cli -i /app/chart.mmd -o /app/output/result.png -w 1800 -H 1080 -b white

